function () {
  const time = String(StartInput.text ?? "").trim();
  const rawDuration = String(DurationInput.text ?? "").trim();
  const duration = Number(rawDuration);
  function reject(reasonCode, message) {
    return {
      available: false,
      reasonCode,
      message
    };
  }
  if (!(/^([01]\d|2[0-3]):[0-5]\d$/).test(time)) {
    return reject("invalid_time", "Enter a start time in HH:MM format.");
  }
  if (rawDuration === "" || !Number.isInteger(duration)) {
    return reject("invalid_time", "Enter a whole number of minutes.");
  }
  const [hours, minutes] = time.split(":").map(Number);
  const start = hours * 60 + minutes;
  const end = start + duration;
  if (end > 1440) {
    return reject("out_of_range", "The slot must end by midnight.");
  }
  if (duration <= 0) {
    return reject("start_not_before_end", "Duration must be greater than zero.");
  }
  if (start <= 540) {
    return reject("start_in_past", "Choose a start time after 09:00.");
  }
  if (duration > 120) {
    return reject("slot_too_long", "The maximum duration is 120 minutes.");
  }
  if (BlockedSwitch.isSwitchedOn) {
    return reject("room_blocked", "Room A101 is blocked.");
  }
  const overlaps = RoomChecker.bookings.some(b => start < b.end && end > b.start);
  if (overlaps) {
    return reject("overlapping_booking", "A101 is booked from 10:00 to 11:00.");
  }
  return {
    available: true,
    reasonCode: "available",
    message: "Room A101 is available."
  };
}

